declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientUserinfoSignedResponseAlgAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientUserinfoSignedResponseAlgAccessor trait.
 *
 * Covers null default, string/VO assignment via withUserinfoSignedResponseAlg,
 * getUserinfoSignedResponseAlg/userinfoSignedResponseAlg accessors, and isUserinfoSignedResponseAlgChanged with/without original.
 */
class TrustedClientUserinfoSignedResponseAlgAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withUserinfoSignedResponseAlg creates a new instance with the UserinfoSignedResponseAlg set
     * from a string value, and getUserinfoSignedResponseAlg returns the primitive string.
     */
    public function testWithUserinfoSignedResponseAlgFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientUserinfoSignedResponseAlgAccessorUnitTest();

        // Act
        $result = $holder->withUserinfoSignedResponseAlg('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getUserinfoSignedResponseAlg());
    }
    /**
     * Asserts that withuserinfoSignedResponseAlg has access to the value object
     * from a string value, and getUserinfoSignedResponseAlg returns the primitive string.
     */
    public function testWithUserinfoSignedResponseAlgFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientUserinfoSignedResponseAlgAccessorUnitTest();

        // Act
        $result = $holder->withUserinfoSignedResponseAlg('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->userinfoSignedResponseAlg()->value());
    }
    public function testChangedUserinfoSignedResponseAlg(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientUserinfoSignedResponseAlgAccessorUnitTest();
        $original = $holder->withUserinfoSignedResponseAlg('one');
        $same = $holder->withUserinfoSignedResponseAlg('one');
        $modified = $holder->withUserinfoSignedResponseAlg('other');

        // Act
        $unchanged = $holder->isUserinfoSignedResponseAlgChanged();
        $withSame = $original->isUserinfoSignedResponseAlgChanged($same);
        $withDiferent = $original->isUserinfoSignedResponseAlgChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientUserinfoSignedResponseAlgAccessorUnitTest
{
    use TrustedClientUserinfoSignedResponseAlgAccessor;
}
